```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;
  return function (...args) {
    const remaining = wait - (Date.now() - last);
    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

const onScroll = throttle(() => {
  console.log(window.scrollY);
}, 200);

window.addEventListener('scroll', onScroll, { passive: true });
```

Fires on first scroll event, then at most once per 200 ms. Trailing timer runs one final call so last scroll position is not missed.

Remove with `window.removeEventListener('scroll', onScroll)`.
